This Terraform configuration creates an AWS Lightsail instance with automatic snapshots enabled. It uses the AWS provider in `us-east-1`, provisions an Ubuntu Lightsail instance, and enables the Lightsail `AutoSnapshot` add-on with a daily snapshot time.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail instance will be created."
  type        = string
  default     = "us-east-1"
}

variable "lightsail_instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "example-lightsail-instance"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail instance."
  type        = string
  default     = "us-east-1a"
}

